command_result.command:
cd /app && python3 - <<'EOF'
p='lib/num/size.c'
s=open(p).read()
a=s.index('    unsigned long long mult = 1;')
b=s.index('    if (*end')
s=s[:a]+'''    unsigned long long mult = 1;
    switch (*end) {
    case 'g':
    case 'G':
        mult = 1024ULL * 1024 * 1024;
        end++;
        break;
    case 'm':
    case 'M':
        mult = 1024ULL * 1024;
        end++;
        break;
    case 'k':
    case 'K':
        mult = 1024;
        end++;
        break;
    default:
        break;
    }
'''+s[b:]
s=s.replace('    *out = (size_t)(n * mult);','    if (n > (unsigned long long)SIZE_MAX / mult)\n        return 0;\n    *out = (size_t)(n * mult);')
s=s.replace('#include <errno.h>','#include <errno.h>\n#include <stdint.h>')
open(p,'w').write(s)
EOF
cat lib/num/size.c | head -20; cat lib/expr/*.[ch]
